import json
import itertools

def solve_puzzle():
    # Define houses
    houses = [1, 2]

    # Attributes and their possible values
    names = ['Arnold', 'Eric']
    book_genres = ['science fiction', 'mystery']
    vacations = ['mountain', 'beach']
    animals = ['cat', 'horse']
    music_genres = ['rock', 'pop']

    solution = None

    # Search through permutations with constraints applied
    for name_perm in itertools.permutations(names):
        idx_Eric = name_perm.index('Eric')

        for book_perm in itertools.permutations(book_genres):
            # Clue 5: The person who loves mystery books is in the first house.
            if book_perm.index('mystery') != 0:
                continue
            idx_mystery = 0

            for music_perm in itertools.permutations(music_genres):
                # Clue 3: The person who loves rock music is the person who loves mystery books.
                if music_perm.index('rock') != idx_mystery:
                    continue
                idx_pop = music_perm.index('pop')

                for vacation_perm in itertools.permutations(vacations):
                    # Clue 1: The person who loves beach vacations is Eric.
                    if vacation_perm.index('beach') != idx_Eric:
                        continue
                    # Clue 2: The person who loves pop music is the person who loves beach vacations.
                    if vacation_perm.index('beach') != idx_pop:
                        continue

                    for animal_perm in itertools.permutations(animals):
                        # Clue 4: The cat lover is not in the second house.
                        if animal_perm.index('cat') == 1:
                            continue

                        # All constraints satisfied; build solution rows
                        rows = []
                        for i, house in enumerate(houses):
                            row = [
                                str(house),
                                name_perm[i],
                                book_perm[i],
                                vacation_perm[i],
                                animal_perm[i],
                                music_perm[i]
                            ]
                            rows.append(row)

                        header = ["House", "Name", "favorite book genres", "type of vacation", "animals", "favorite music genres"]
                        solution = {
                            "solution": {
                                "header": header,
                                "rows": rows
                            }
                        }
                        return solution

    return None

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False, indent=2))
